begin;
-- LC editorial migration — módulo 4: Repetições
update nexora.lessons set objective='Reconhecer tarefas repetitivas que devem ser representadas por laços e distinguir repetição controlada de cópia manual de instruções.',estimated_minutes=21,content='[{"type":"story","title":"Copiar a mesma instrução cinco vezes parece simples — até virar cinquenta","body":"Se precisamos mostrar os números de 1 a 5, poderíamos escrever cinco comandos. Mas e se amanhã forem 100 números? Ou uma lista com quantidade variável de itens?\n\nLaços existem para representar uma ação que se repete segundo uma regra. Em vez de duplicar instruções, descrevemos o padrão da repetição."},{"type":"concept","title":"Laço é uma estrutura que executa um bloco várias vezes","body":"Toda repetição precisa de algum mecanismo de controle: uma sequência conhecida, uma condição que muda ou uma coleção a ser percorrida.\n\nO objetivo não é repetir por repetir. É expressar claramente quando começar, quando continuar e quando terminar."},{"type":"comparison","title":"Repetição manual × repetição modelada","items":["Manual: escrever a mesma ação várias vezes.","Laço: escrever a ação uma vez e definir como ela se repete.","Manual funciona apenas para quantidade fixa e pequena.","Laço adapta-se melhor a quantidades variáveis e reduz duplicação."]},{"type":"example","title":"Mostrar de 1 a 5","body":"Em vez de cinco linhas independentes, podemos pensar:\n\ncomeçar em 1 → mostrar valor → avançar para o próximo → repetir até 5.\n\nJá existe um início, uma ação, uma atualização e um fim."},{"type":"guided","title":"Qual tarefa pede um laço?","question":"Qual situação é mais naturalmente resolvida com repetição?","options":["Calcular uma única soma de dois números.","Percorrer todos os produtos de um carrinho para calcular o total.","Escolher entre aprovado e reprovado.","Guardar o nome de um cliente."],"answer":1,"feedback":"Correto. A mesma regra precisa ser aplicada a uma quantidade de itens que pode variar.","feedback_incorrect":"Procure a tarefa em que o mesmo tipo de ação precisa acontecer para vários elementos."},{"type":"mistake","title":"Laço sem condição de término é um risco","body":"Uma repetição precisa avançar em direção a um fim. Se a condição nunca muda, o algoritmo pode ficar preso. Sempre consiga explicar o que faz o laço terminar."},{"type":"recap","items":["Laços representam padrões repetitivos.","Eles reduzem duplicação de instruções.","Toda repetição precisa de controle e término.","Antes de criar um laço, identifique o que se repete e o que muda a cada ciclo."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Reconhecer tarefas repetitivas que devem ser representadas por laços e distinguir repetição controlada de cópia manual de instruções.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual característica indica que uma tarefa provavelmente precisa de laço?","options":["A mesma operação deve ser aplicada a vários itens.","Existe apenas um valor fixo.","Há somente uma decisão binária.","Nenhum dado muda."],"answer":0,"feedback":"Correto. A repetição aparece quando um padrão precisa ser reaplicado.","feedback_incorrect":"Procure o cenário com execução repetida de uma mesma lógica."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=1;
update nexora.lessons set objective='Usar um contador para acompanhar quantas vezes um evento ocorreu, definindo valor inicial, regra de incremento e condição que determina quando contar.',estimated_minutes=22,content='[{"type":"story","title":"Contar é diferente de somar valores","body":"Uma loja quer saber quantas vendas do dia foram concluídas. O valor financeiro de cada venda não importa para essa pergunta; o que importa é quantas atendem ao critério.\n\nUm contador registra ocorrências. Ele normalmente começa em zero e aumenta quando o evento desejado acontece."},{"type":"concept","title":"Contador guarda quantidade de ocorrências","body":"O padrão básico é: iniciar `contador = 0`, percorrer os dados e incrementar quando a condição for satisfeita.\n\nO contador não precisa aumentar em toda repetição. Ele aumenta quando o evento que estamos contando acontece."},{"type":"example","title":"Quantas notas são maiores ou iguais a 7?","body":"Notas: [8, 5, 7, 9].\n\nComeçamos contador=0.\n8 atende → 1.\n5 não atende → continua 1.\n7 atende → 2.\n9 atende → 3.\n\nResultado: três notas satisfazem a regra."},{"type":"mechanics","title":"Três decisões constroem um contador","items":["Qual evento estou contando?","Qual condição identifica esse evento?","Quanto o contador aumenta quando ele acontece?"]},{"type":"guided","title":"Quando incrementar?","question":"Queremos contar pedidos cancelados. Em qual momento o contador deve aumentar?","options":["Em todo pedido.","Somente quando status == cancelado.","Somente quando o valor for maior que zero.","Antes de ler o status."],"answer":1,"feedback":"Correto. O incremento precisa estar ligado ao evento contado.","feedback_incorrect":"O contador deve mudar apenas quando o critério que define a ocorrência for satisfeito."},{"type":"mistake","title":"Inicializar dentro do laço apaga o histórico","body":"Se `contador = 0` for executado em cada repetição, o valor acumulado é perdido. A inicialização deve acontecer antes do laço; o incremento, dentro dele."},{"type":"recap","items":["Contador mede quantidade de ocorrências.","Normalmente começa em zero.","O incremento depende do evento contado.","Inicializar no lugar errado destrói o histórico."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Usar um contador para acompanhar quantas vezes um evento ocorreu, definindo valor inicial, regra de incremento e condição que determina quando contar.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Um contador de tentativas deve começar em 0 e aumentar a cada tentativa. Depois de 4 tentativas, qual valor esperamos?","options":["0","1","3","4"],"answer":3,"feedback":"Correto. Uma unidade foi acrescentada por tentativa.","feedback_incorrect":"Acompanhe o incremento a cada ocorrência."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=2;
update nexora.lessons set objective='Usar acumuladores para combinar uma sequência de valores em um total, distinguindo o padrão de acumulação do padrão de contagem.',estimated_minutes=23,content='[{"type":"story","title":"Contar vendas não é o mesmo que somar receita","body":"Se tivemos três vendas de R$ 100, R$ 250 e R$ 50, o contador responde “3 vendas”. O acumulador responde “R$ 400”.\n\nAmbos usam repetição, mas guardam informações diferentes."},{"type":"concept","title":"Acumulador combina valores progressivamente","body":"Um acumulador geralmente começa com um valor neutro, como zero para soma. Em cada repetição, incorpora o valor atual: `total = total + valor`.\n\nO novo total depende do total anterior, por isso ele carrega o histórico da sequência."},{"type":"example","title":"Somando vendas","body":"Valores: 100, 250, 50.\n\nTotal=0.\nApós 100 → 100.\nApós 250 → 350.\nApós 50 → 400.\n\nO resultado final representa todos os valores processados."},{"type":"comparison","title":"Contador × acumulador","items":["Contador: quantas ocorrências aconteceram.","Acumulador: quanto os valores combinados representam.","Contador normalmente soma 1.","Acumulador normalmente soma o valor atual ou outra transformação dele."]},{"type":"guided","title":"Qual variável é acumulador?","question":"Em `total = total + preco`, qual papel `total` exerce?","options":["Constante.","Acumulador.","Booleano de decisão.","Parâmetro sem estado."],"answer":1,"feedback":"Correto. O novo valor incorpora o histórico anterior e o preço atual.","feedback_incorrect":"Observe que o valor anterior de `total` participa do próximo valor."},{"type":"mistake","title":"Não reinicie o acumulador a cada item","body":"Assim como o contador, o acumulador precisa ser inicializado antes da repetição. Reiniciá-lo dentro do laço faz o algoritmo lembrar apenas do item atual."},{"type":"recap","items":["Acumuladores combinam valores ao longo da repetição.","O total anterior participa da próxima atualização.","Contador e acumulador resolvem perguntas diferentes.","O valor inicial deve ser escolhido de acordo com a operação."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Usar acumuladores para combinar uma sequência de valores em um total, distinguindo o padrão de acumulação do padrão de contagem.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Para calcular o total de uma lista de preços, qual padrão é adequado?","options":["Iniciar total=0 e somar cada preço ao total.","Iniciar total=1 e contar itens.","Guardar apenas o último preço.","Reiniciar total=0 em cada item."],"answer":0,"feedback":"Correto. O acumulador preserva e atualiza o total.","feedback_incorrect":"O total precisa carregar o resultado parcial entre as repetições."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=3;
update nexora.lessons set objective='Escolher uma repetição do tipo PARA quando a sequência ou quantidade de iterações é conhecida, acompanhando corretamente valor inicial, avanço e limite.',estimated_minutes=23,content='[{"type":"story","title":"Quando sabemos por onde vamos passar","body":"Mostrar números de 1 a 10, processar cada mês do ano ou percorrer posições conhecidas de uma coleção são tarefas em que a sequência já é previsível.\n\nNesses casos, um laço do tipo PARA comunica bem a intenção: repetir para cada valor de uma sequência."},{"type":"concept","title":"PARA percorre uma sequência controlada","body":"O laço define um conjunto ou intervalo de valores e executa o bloco uma vez para cada elemento. A própria estrutura normalmente cuida do avanço.\n\nIsso reduz erros de atualização manual quando a quantidade de passos já é conhecida."},{"type":"example","title":"De 1 até 5","body":"Pense em:\nPARA numero de 1 até 5\n    mostrar numero\nFIM\n\nO corpo executa cinco vezes, e cada repetição recebe um valor diferente da sequência."},{"type":"comparison","title":"Use PARA quando a pergunta for “para cada...”","items":["Para cada produto do carrinho.","Para cada dia de uma semana conhecida.","Para cada número de 1 até 10.","Quando não sabemos quantas tentativas serão necessárias, outra estrutura pode comunicar melhor."]},{"type":"guided","title":"Qual cenário combina melhor com PARA?","question":"Qual tarefa tem quantidade de iterações conhecida desde o início?","options":["Pedir senha até acertar.","Processar exatamente 12 meses.","Repetir enquanto houver erro.","Tentar conexão até o servidor responder."],"answer":1,"feedback":"Correto. A sequência de 12 meses já é conhecida.","feedback_incorrect":"Procure o cenário em que podemos determinar antecipadamente quantas posições serão percorridas."},{"type":"mistake","title":"Cuidado com início, fim e inclusão do limite","body":"Linguagens diferem na forma de representar intervalos. Antes de confiar na sintaxe, verifique se o valor final está incluído e quantas iterações realmente ocorrerão."},{"type":"recap","items":["PARA é adequado para sequências conhecidas.","Cada iteração recebe um valor da sequência.","A estrutura costuma controlar o avanço.","Limites e quantidade de repetições devem ser testados."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Escolher uma repetição do tipo PARA quando a sequência ou quantidade de iterações é conhecida, acompanhando corretamente valor inicial, avanço e limite.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Para processar cada dia de uma lista com 7 dias, qual estrutura expressa melhor a intenção?","options":["Uma decisão única.","Um PARA para cada dia.","Uma constante sem repetição.","Um SENÃO."],"answer":1,"feedback":"Correto. A tarefa é repetir a mesma lógica para cada elemento conhecido.","feedback_incorrect":"A frase “para cada” indica diretamente um padrão de iteração."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=4;
update nexora.lessons set objective='Usar ENQUANTO quando a repetição depende de uma condição que pode mudar durante a execução, garantindo progresso e uma saída possível.',estimated_minutes=24,content='[{"type":"story","title":"Nem sempre sabemos quantas tentativas serão necessárias","body":"Um usuário pode acertar a senha na primeira tentativa ou apenas na terceira. Um sistema pode processar itens até a fila ficar vazia. Nesses casos, a quantidade de repetições não é conhecida antecipadamente.\n\nO importante é saber qual condição mantém o processo acontecendo."},{"type":"concept","title":"ENQUANTO repete enquanto a condição for verdadeira","body":"Antes de cada ciclo, a condição é verificada. Se for verdadeira, o bloco executa. Depois, alguma coisa precisa mudar para que, em algum momento, a condição possa se tornar falsa.\n\nEsse “progresso” é essencial para evitar laços infinitos."},{"type":"example","title":"Até três tentativas","body":"tentativas = 0\nENQUANTO tentativas < 3\n    realizar tentativa\n    tentativas = tentativas + 1\nFIM\n\nA atualização aproxima o estado do limite 3. Sem ela, a condição continuaria verdadeira para sempre."},{"type":"mechanics","title":"Revise um ENQUANTO com quatro perguntas","items":["Qual condição mantém a repetição?","Qual estado pode mudar essa condição?","Onde esse estado é atualizado?","Existe algum cenário em que o laço nunca termina?"]},{"type":"guided","title":"Encontre o risco de laço infinito","question":"`ENQUANTO tentativas < 3` usa `tentativas=0`, mas o valor nunca é alterado. O que acontece?","options":["Executa três vezes.","Executa uma vez.","Pode repetir indefinidamente.","Não executa."],"answer":2,"feedback":"Correto. A condição nunca se aproxima de falso.","feedback_incorrect":"Sem atualização, `tentativas` continua 0 e a condição permanece verdadeira."},{"type":"mistake","title":"Condição correta sem atualização ainda é algoritmo incorreto","body":"É comum olhar apenas para a condição e esquecer que o estado precisa mudar. Ao revisar um laço, identifique explicitamente a instrução responsável pelo progresso."},{"type":"recap","items":["ENQUANTO é útil quando a quantidade de ciclos não é conhecida.","A condição é testada antes de cada repetição.","O estado precisa mudar em direção ao término.","Todo laço deve ter uma saída possível."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Usar ENQUANTO quando a repetição depende de uma condição que pode mudar durante a execução, garantindo progresso e uma saída possível.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual elemento evita que `ENQUANTO saldo > 0` execute para sempre, se o objetivo é consumir saldo?","options":["Atualizar o saldo dentro do laço.","Declarar uma constante.","Adicionar outro nome de variável sem alterar saldo.","Remover a condição."],"answer":0,"feedback":"Correto. O estado usado na condição precisa mudar.","feedback_incorrect":"O laço termina quando a condição pode se tornar falsa; algo precisa alterar o saldo."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=5;
update nexora.lessons set objective='Percorrer listas aplicando a mesma operação a cada elemento e combinar iteração com contadores ou acumuladores de forma clara.',estimated_minutes=23,content='[{"type":"story","title":"Listas dão um alvo natural para a repetição","body":"Uma turma tem várias notas. Um carrinho tem vários produtos. Uma fila tem vários atendimentos. Quando os dados vêm em coleção, frequentemente precisamos executar a mesma lógica para cada elemento.\n\nPercorrer uma lista é aplicar um padrão de repetição aos itens que ela contém."},{"type":"concept","title":"Cada iteração trabalha com um elemento da coleção","body":"Em vez de criar `nota1`, `nota2`, `nota3`, armazenamos as notas em uma lista e percorremos cada item. O corpo do laço pode somar, contar, comparar ou transformar o valor atual.\n\nA quantidade de itens pode mudar sem exigir que o algoritmo seja reescrito."},{"type":"example","title":"Média de uma lista","body":"Notas: [8, 7, 9].\n\nPercorrer cada nota → acumular total = 24.\nQuantidade de itens = 3.\nMédia = 24 / 3 = 8.\n\nAqui, lista, laço e acumulador trabalham juntos."},{"type":"comparison","title":"Item atual não é a lista inteira","body":"Durante uma iteração, normalmente trabalhamos com um elemento por vez. Confundir o item atual com a coleção completa pode levar a operações repetidas ou resultados duplicados."},{"type":"guided","title":"O que muda em cada ciclo?","question":"Ao percorrer `[10,20,30]`, o que normalmente representa a variável `valor` dentro do laço?","options":["A lista inteira sempre.","O elemento atual da iteração.","Uma constante que nunca muda.","A quantidade total de listas."],"answer":1,"feedback":"Correto. Cada ciclo expõe um elemento da coleção.","feedback_incorrect":"O laço percorre a coleção; a variável de iteração representa o item atual."},{"type":"mistake","title":"Lista vazia precisa ser considerada","body":"Um laço sobre lista vazia executa zero vezes. Se o algoritmo divide o total pela quantidade de itens depois, pode surgir divisão por zero. A validação do estado da coleção continua importante."},{"type":"recap","items":["Listas permitem quantidade variável de elementos.","O laço trabalha com um item por iteração.","Contadores e acumuladores podem ser usados durante o percurso.","Coleções vazias são casos de teste importantes."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Percorrer listas aplicando a mesma operação a cada elemento e combinar iteração com contadores ou acumuladores de forma clara.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Ao calcular média de uma lista vazia, qual cuidado é necessário?","options":["Dividir por zero normalmente.","Tratar a ausência de itens antes da divisão.","Adicionar um item fictício.","Ignorar a quantidade de elementos."],"answer":1,"feedback":"Correto. A lista vazia torna a divisão inválida.","feedback_incorrect":"A fórmula da média depende de uma quantidade maior que zero."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=6;
update nexora.lessons set objective='Combinar laços e condições para selecionar, contar ou acumular apenas elementos que atendam a uma regra, testando o comportamento com listas variadas.',estimated_minutes=25,content='[{"type":"story","title":"Nem todo item percorrido precisa participar do resultado","body":"Uma empresa tem uma lista de vendas, mas quer somar apenas as concluídas. O laço percorre todas; a condição decide quais entram no acumulador.\n\nÉ nessa combinação que repetições começam a resolver problemas realmente úteis."},{"type":"concept","title":"O laço encontra os itens; a condição decide o que fazer com cada um","body":"Percorrer e decidir são responsabilidades diferentes. O laço garante que cada elemento seja visitado. Dentro dele, uma condição pode filtrar comportamentos: contar, somar, ignorar ou classificar."},{"type":"example","title":"Somar apenas vendas concluídas","body":"Para cada venda:\n    SE status == concluída\n        total = total + valor\n\nUma venda cancelada ainda é percorrida, mas não altera o total."},{"type":"comparison","title":"Filtrar durante o laço × alterar a coleção","body":"Nem sempre é necessário remover itens da lista original. Muitas vezes basta decidir, durante a iteração, quais elementos participam do resultado. Isso evita mutações desnecessárias."},{"type":"guided","title":"Onde fica a condição?","question":"Queremos contar apenas notas abaixo de 7. Qual padrão é correto?","options":["Incrementar contador em toda nota.","Dentro do laço, testar `nota < 7` e só então incrementar.","Testar uma única nota antes do laço.","Somar as notas em vez de contar."],"answer":1,"feedback":"Correto. A condição seleciona quais iterações alteram o contador.","feedback_incorrect":"O laço visita todas as notas; a condição decide quais entram na contagem."},{"type":"mastery","title":"Você domina repetições quando consegue","items":["Identificar o que se repete.","Escolher PARA ou ENQUANTO pela forma de controle.","Usar contador e acumulador corretamente.","Percorrer listas sem depender de quantidade fixa.","Combinar condições sem perder clareza.","Explicar como o laço termina e quais casos podem falhar."]},{"type":"recap","items":["Laços e condições resolvem seleção dentro de coleções.","Nem todo item precisa alterar o resultado.","Contadores e acumuladores podem depender de condições.","Testes devem incluir listas vazias, itens que passam e itens que não passam no filtro."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Repetições","concept":"Combinar laços e condições para selecionar, contar ou acumular apenas elementos que atendam a uma regra, testando o comportamento com listas variadas.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma lista possui vendas concluídas e canceladas. Para somar apenas as concluídas, qual estratégia é correta?","options":["Somar todas e depois adivinhar o valor cancelado.","Percorrer todas e adicionar ao total apenas quando status == concluída.","Ignorar o status.","Reiniciar o total a cada item."],"answer":1,"feedback":"Correto. O laço percorre; a condição filtra; o acumulador soma.","feedback_incorrect":"Separe as responsabilidades: percorrer, decidir e acumular."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=7;
update nexora.questions set prompt='Qual situação indica mais claramente necessidade de laço?',options='[{"id":"a","label":"Aplicar a mesma regra a todos os itens de uma lista."},{"id":"b","label":"Somar apenas dois números fixos."},{"id":"c","label":"Guardar um nome."},{"id":"d","label":"Escolher entre dois caminhos uma vez."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. O padrão precisa ser repetido para vários elementos.',feedback_incorrect='Procure a tarefa com execução recorrente da mesma lógica.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=1;
update nexora.questions set prompt='Para contar pedidos cancelados, quando o contador deve aumentar?',options='[{"id":"a","label":"Em todos os pedidos."},{"id":"b","label":"Somente quando status == cancelado."},{"id":"c","label":"Antes de iniciar o laço."},{"id":"d","label":"Depois de apagar o status."}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. O incremento acompanha a ocorrência contada.',feedback_incorrect='O contador deve mudar apenas quando o evento acontece.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=2;
update nexora.questions set prompt='Qual padrão calcula a soma de vários preços?',options='[{"id":"a","label":"Contador que soma 1."},{"id":"b","label":"Acumulador que adiciona cada preço ao total."},{"id":"c","label":"Variável que guarda apenas o último preço."},{"id":"d","label":"Reinicialização do total em cada ciclo."}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. O acumulador preserva o resultado parcial.',feedback_incorrect='A soma precisa carregar o histórico entre os itens.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=3;
update nexora.questions set prompt='Qual cenário combina melhor com um PARA?',options='[{"id":"a","label":"Processar exatamente os 12 meses do ano."},{"id":"b","label":"Tentar senha até acertar."},{"id":"c","label":"Repetir enquanto existir erro."},{"id":"d","label":"Esperar evento sem saber quando ocorrerá."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. A sequência é conhecida antecipadamente.',feedback_incorrect='PARA comunica melhor uma sequência ou quantidade conhecida.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=4;
update nexora.questions set prompt='O que um ENQUANTO precisa para não ficar preso quando a condição começa verdadeira?',options='[{"id":"a","label":"Uma atualização capaz de tornar a condição falsa."},{"id":"b","label":"Apenas um nome de variável."},{"id":"c","label":"Uma constante que nunca muda."},{"id":"d","label":"Remover qualquer condição."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. O estado precisa progredir em direção ao término.',feedback_incorrect='Identifique o que muda a condição ao longo das repetições.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=5;
update nexora.questions set prompt='Ao percorrer uma lista, a variável de iteração normalmente representa:',options='[{"id":"a","label":"O item atual."},{"id":"b","label":"Sempre a lista inteira."},{"id":"c","label":"Uma constante global."},{"id":"d","label":"O número total de programas."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. Cada ciclo trabalha com um elemento.',feedback_incorrect='O laço visita os elementos um a um.',difficulty=3 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=6;
insert into nexora.questions(id,assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select gen_random_uuid(),(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1),'Para somar apenas vendas concluídas, qual combinação é adequada?','multiple_choice','[{"id":"a","label":"Laço + condição + acumulador."},{"id":"b","label":"Somente uma constante."},{"id":"c","label":"Somente um SENÃO."},{"id":"d","label":"Contador reiniciado a cada venda."}]'::jsonb,'{"option_id":"a"}'::jsonb,'Correto. Cada estrutura resolve uma parte do problema.','Precisamos percorrer, selecionar e somar.',3,7
where not exists(select 1 from nexora.questions where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1) and position=7);
update nexora.assessments set title='Checkpoint aplicado — Repetições',pass_score=70,max_attempts=3 where id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) order by a.created_at asc limit 1);
update nexora.learning_resources set title='Apostila LC — Repetições',summary='Revisão integrada de laços, contadores, acumuladores, listas e condições.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"1. Repetição modela padrões recorrentes","body":"Identifique a ação que se repete, o estado que muda e a condição que encerra o processo."},{"title":"2. Contadores medem ocorrências","body":"Começam normalmente em zero e aumentam quando um evento definido acontece."},{"title":"3. Acumuladores combinam valores","body":"Carregam o resultado parcial e incorporam o valor atual a cada iteração."},{"title":"4. PARA percorre sequências conhecidas","body":"Use quando a quantidade ou coleção já está definida."},{"title":"5. ENQUANTO depende de condição dinâmica","body":"O estado precisa mudar para que o laço possa terminar."},{"title":"6. Listas e laços trabalham juntos","body":"Cada iteração recebe um item da coleção; o algoritmo deixa de depender de quantidade fixa."},{"title":"7. Condições selecionam o que participa","body":"Dentro do laço, condições podem contar, somar ou ignorar elementos."},{"title":"Exercícios","items":["Conte quantas notas estão abaixo de 7.","Some apenas vendas com status concluída.","Modele três tentativas de senha.","Calcule média de uma lista tratando lista vazia."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=1;
update nexora.learning_resources set title='Guia de diagnóstico de laços',summary='Checklist para encontrar laços infinitos, contagens erradas e acumuladores reiniciados.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Perguntas essenciais","items":["O que se repete?","O que muda em cada ciclo?","Como o laço termina?","O contador/acumulador foi inicializado antes do laço?","O incremento ocorre na condição correta?","A coleção pode estar vazia?"]},{"title":"Erros frequentes","items":["Atualização ausente no ENQUANTO.","Contador reiniciado dentro do laço.","Acumulador usando valor inicial inadequado.","Limite do PARA fora por uma posição.","Divisão por zero após lista vazia."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=2;
update nexora.learning_resources set title='Desafio aplicado — Resumo de vendas',summary='Atividade para percorrer vendas, filtrar status e produzir indicadores com contadores e acumuladores.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Cenário","body":"Uma lista contém vendas com valor e status. Produza total vendido, quantidade de vendas concluídas, quantidade cancelada e ticket médio das concluídas."},{"title":"Requisitos","items":["Percorra a lista uma única vez, se possível.","Use contadores separados por objetivo.","Some apenas valores de vendas concluídas.","Trate lista sem vendas concluídas.","Teste lista vazia, uma venda e mistura de status."]},{"title":"Critério","body":"Os indicadores precisam ser reproduzíveis a partir dos dados de teste e a lógica deve explicar claramente quando cada variável muda."}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=4 limit 1) and position=3;
commit;
